  PregFaq(
    id: 'PREG-CANI-EAT-009',
    number: 92,
    month: 2,
    question: 'Is non-veg (chicken, eggs, mutton) safe in pregnancy?',
    category: 'Food (Can I > Eat)',
    applicability: 'All trimesters',
    canI: 'Eat',
    sensitivity: 'No',
    parts: [
      PregFaqPart(PregFaqSection.direct, '', [
        'Chicken, eggs, mutton and other non-veg are safe and nourishing in pregnancy, as long as they are cooked thoroughly, no pink meat, firm egg yolks, and juices running clear. The main rule is simply to avoid anything raw or undercooked.',
      ], []),
      PregFaqPart(PregFaqSection.why, '', [
        'Well-cooked meat and eggs are excellent sources of protein and easily absorbed iron, which helps against anaemia, common in Indian pregnancies. The caution is that raw or undercooked meat, poultry and eggs can carry bacteria and parasites like salmonella, listeria and toxoplasma, which your lowered pregnancy immunity handles less well. Thorough cooking destroys these. The idea that chicken or mutton is "garam" and harmful is a myth; what matters is cooking, not "heat".',
      ], []),
      PregFaqPart(PregFaqSection.forYou, '', [
        'Cook chicken until there is no pink and juices run clear, cook eggs until both white and yolk are firm (so skip runny or half-fried eggs), and cook mutton well done. Handle raw meat hygienically, washing hands, knives and boards, and keeping it away from ready-to-eat food. Enjoy it a few times a week as part of a varied diet, and limit liver, which is very high in vitamin A.',
      ], []),
      PregFaqPart(PregFaqSection.doctor, '', [
        'See your doctor if you develop fever, vomiting or diarrhoea after eating, and ask for guidance if you eat liver often.',
      ], []),
      PregFaqPart(PregFaqSection.perspective, '', [
        'For non-veg families, well-cooked meat and eggs are a genuine asset in pregnancy, not something to fear.',
      ], []),
      PregFaqPart(PregFaqSection.takeaways, '', [], [
        'Non-veg is safe and nourishing when thoroughly cooked.',
        'No pink meat, firm egg yolks, clear juices.',
        'Avoid raw or undercooked meat and eggs.',
        'Handle raw meat hygienically.',
        'Limit liver (high vitamin A); the "garam" fear is a myth.',
      ]),
    ],
    related: [
      'PREG-CANI-EAT-001',
      'PREG-CANI-EAT-004',
      'PREG-HEALTH-006',
    ],
  ),
  PregFaq(
